37	
38	std::shared_ptr<StreamChannel> StreamChannel::create()
39	{
40	    // std::make_shared cannot access the private constructor; use the new/shared_ptr form.
41	    return std::shared_ptr<StreamChannel>(new StreamChannel());
42	}
43	
44	void StreamChannel::push(StreamChunk chunk)
45	{
46	    {
47	        std::lock_guard<std::mutex> lk(mMutex);
48	        mPending.push_back(std::move(chunk));
49	    }
50	    mCv.notify_one();
51	}
52	
53	void StreamChannel::finish(FinishReason r)
54	{
55	    {
56	        std::lock_guard<std::mutex> lk(mMutex);
57	        if (mFinished.load(std::memory_order_relaxed))
58	        {
59	            return; // Idempotent — first caller wins.
60	        }
61	        mReason.store(r, std::memory_order_release);
62	        mFinished.store(true, std::memory_order_release);
63	    }
64	    mCv.notify_all();
65	}
66	
67	void StreamChannel::setOriginalBatchIdx(int32_t idx) noexcept
68	{
69	    mOriginalBatchIdx.store(idx, std::memory_order_release);
70	}
71	
72	bool StreamChannel::isFinished() const noexcept
73	{
74	    return mFinished.load(std::memory_order_acquire);
75	}
76	
77	FinishReason StreamChannel::getReason() const noexcept
78	{
79	    if (!mFinished.load(std::memory_order_acquire))
80	    {
81	        return FinishReason::kNotFinished;
82	    }
83	    return mReason.load(std::memory_order_relaxed);
84	}
85	
86	int32_t StreamChannel::getOriginalBatchIdx() const noexcept
87	{
88	    return mOriginalBatchIdx.load(std::memory_order_acquire);
89	}
90	
91	bool StreamChannel::isCancelled() const noexcept
92	{
93	    return mCancelled.load(std::memory_order_acquire);
94	}
95	
96	void StreamChannel::cancel() noexcept
97	{
98	    mCancelled.store(true, std::memory_order_release);
99	    {
100	        std::lock_guard<std::mutex> lk(mMutex);
101	    }
102	    mCv.notify_all();
103	}
104	
105	void StreamChannel::setStreamInterval(int32_t n) noexcept
106	{
107	    mStreamInterval.store(std::max(1, n), std::memory_order_release);
108	}
