156	//=============================================================================
157	// Streaming helpers — free functions (friends of StreamChannel)
158	//=============================================================================
159	
160	void attachStreamChannel(std::shared_ptr<StreamChannel> const& channel, int32_t originalIdx)
161	{
162	    bool const wasAttached = channel->mAttachedToRequest.exchange(true, std::memory_order_acq_rel);
163	    if (wasAttached)
164	    {
165	        // validateStreamingSubmission should have caught this; belt-and-suspenders.
166	        throw std::runtime_error("StreamChannel already attached to a live request");
167	    }
168	    channel->setOriginalBatchIdx(originalIdx);
169	}
170	
171	bool validateStreamingSubmission(LLMGenerationRequest const& request)
172	{
173	    if (request.streamChannels.empty())
174	    {
175	        return true;
176	    }
177	    if (request.streamChannels.size() != request.requests.size())
178	    {
179	        LOG_ERROR("streamChannels size (%zu) must equal requests size (%zu)", request.streamChannels.size(),
180	            request.requests.size());
181	        return false;
182	    }
183	    for (auto const& ch : request.streamChannels)
184	    {
185	        if (!ch)
186	        {
187	            continue; // Null entry opts out of streaming for this slot.
188	        }
189	        if (ch->isFinished())
190	        {
191	            LOG_ERROR("StreamChannel already finished — create a new channel per request");
192	            return false;
193	        }
194	        if (ch->mAttachedToRequest.load(std::memory_order_acquire))
195	        {
196	            LOG_ERROR("StreamChannel already attached to a live request — concurrent reuse forbidden");
197	            return false;
198	        }
199	    }
200	    return true;
201	}
202	
203	char const* finishReasonName(FinishReason r) noexcept
204	{
205	    switch (r)
206	    {
207	    case FinishReason::kNotFinished: return "not-finished";
208	    case FinishReason::kEndId: return "end-of-sequence";
209	    case FinishReason::kLength: return "max-length";
210	    case FinishReason::kCancelled: return "cancelled";
211	    case FinishReason::kError: return "error";
212	    case FinishReason::kStopWords: return "stop-words";
213	    }
214	    return "?";
215	}
216	
217	StopMatchOutcome applyStopStringMatch(
218	    std::string& buffer, std::vector<std::string> const& stops, size_t maxStopLen, bool isFinal)
219	{
220	    StopMatchOutcome out;
221	
222	    // maxStopLen == 0 ⇒ no stops or all-empty entries — pass-through.
223	    if (maxStopLen == 0)
224	    {
225	        out.emitted = std::move(buffer);
226	        buffer.clear();
227	        return out;
228	    }
229	
230	    // Earliest-position-wins across all non-empty stops.
231	    size_t earliest = std::string::npos;
232	    for (auto const& stop : stops)
233	    {
234	        if (stop.empty())
235	        {
236	            continue;
237	        }
238	        size_t const pos = buffer.find(stop);
239	        if (pos < earliest)
240	        {
241	            earliest = pos;
242	        }
243	    }
244	
245	    if (earliest != std::string::npos)
246	    {
247	        // Matched — emit everything before the match, drop the rest.
248	        out.emitted = buffer.substr(0, earliest);
249	        buffer.clear();
250	        out.stopMatched = true;
251	        return out;
252	    }
253	
254	    if (isFinal)
255	    {
256	        // Final flush: nothing held back.
257	        out.emitted = std::move(buffer);
258	        buffer.clear();
259	        return out;
260	    }
261	
262	    // No match yet: hold back the last (maxStopLen - 1) bytes so a stop string
263	    // straddling the emit/buffer boundary is detected on the next iteration.
264	    size_t const holdBack = maxStopLen - 1;
265	    if (buffer.size() <= holdBack)
266	    {
267	        // Whole buffer must be retained — nothing safe to emit.
268	        return out; // out.emitted stays empty
269	    }
270	    size_t const safeLen = buffer.size() - holdBack;
271	    out.emitted = buffer.substr(0, safeLen);
272	    buffer.erase(0, safeLen);
273	    return out;
274	}
275	
276	void applyCancellationToFinishStates(DecodingInferenceContext& context)
277	{
278	    for (int32_t i = 0; i < context.activeBatchSize; ++i)
279	    {
280	        auto& s = context.slotStreams[i];
281	        if (!s.channel)
282	        {
283	            continue;
284	        }
285	        if (context.finishedStates[i])
286	        {
287	            continue; // First-writer-wins: don't overwrite a natural-finish reason.
288	        }
289	        if (s.channel->mCancelled.load(std::memory_order_acquire))
290	        {
291	            context.finishedStates[i] = 1;
292	            s.terminalReason = FinishReason::kCancelled;
293	            LOG_DEBUG("Batch %d finished, reason: cancel", i);
294	        }
295	    }
296	}
297	
298	void decodePerSlot(DecodingInferenceContext& context, tokenizer::Tokenizer const& tok)
299	{
300	    for (int32_t i = 0; i < context.activeBatchSize; ++i)
301	    {
302	        auto& s = context.slotStreams[i];
303	        auto const& slotStops = context.stopStringsPerSlot[i];
304	        bool const hasChannel = (s.channel != nullptr);
305	        bool const slotStopsEnabled = !slotStops.empty();
306	
307	        s.stopMatchedThisIter = false;
308	        s.pendingEmitText.clear();
309	
310	        // Fast path: slot needs neither chunk emission nor stop detection.
311	        if (!hasChannel && !slotStopsEnabled)
312	        {
313	            continue;
314	        }
315	
316	        bool const isFinal = context.finishedStates[i] != 0;
317	
318	        // Stream-interval gating; non-streaming slots run detection every iter.
319	        if (hasChannel)
320	        {
321	            int32_t const streamInterval = s.channel->getStreamInterval();
322	            size_t const newlyAvailable = context.tokenIds[i].size() - s.sentTokenCount;
323	            bool const intervalMet = static_cast<int32_t>(newlyAvailable) >= streamInterval;
324	            if (!isFinal && !intervalMet)
325	            {
326	                continue;
327	            }
328	        }
329	
330	        // For non-streaming slots there is no channel to read skipSpecial from;
331	        // default to true (matches Tokenizer::decode(..., true) used in finalization).
332	        bool const skipSpecial = hasChannel ? s.channel->getSkipSpecialTokens() : true;
333	        std::string delta = tokenizer::emitDelta(s, tok, context.tokenIds[i], skipSpecial);
334	        if (isFinal && !s.pendingBytes.empty())
335	        {
336	            delta.append(tokenizer::emitDeltaFlush(s));
337	        }
338	
339	        // Stop match overrides kEndId/kLength but not kCancelled/kError. The
340	        // override itself is applied by updateFinishStates based on stopMatchedThisIter.
341	        bool const stopActive = slotStopsEnabled && s.terminalReason != FinishReason::kCancelled
342	            && s.terminalReason != FinishReason::kError;
343	        if (stopActive)
344	        {
345	            s.stopMatchBuffer.append(delta);
346	            auto outcome = applyStopStringMatch(s.stopMatchBuffer, slotStops, s.maxStopLen, isFinal);
347	            s.pendingEmitText = std::move(outcome.emitted);
348	            s.stopMatchedThisIter = outcome.stopMatched;
349	        }
350	        else
351	        {
352	            s.pendingEmitText = std::move(delta);
353	        }
354	    }
355	}
356	
357	void emitChunks(DecodingInferenceContext& context, tokenizer::Tokenizer const& tokenizer)
358	{
359	    for (int32_t i = 0; i < context.activeBatchSize; ++i)
360	    {
361	        auto& s = context.slotStreams[i];
362	        if (!s.channel)
363	        {
364	            continue; // non-streaming: output assembled at handleRequest finalization
365	        }
366	
367	        bool const isFinal = context.finishedStates[i] != 0;
368	        if (s.pendingEmitText.empty() && !isFinal)
369	        {
370	            continue;
371	        }
372	
373	        StreamChunk chunk;
374	        // Delta tokens span [lastEmittedTokenCount, sentTokenCount) — accumulates
375	        // across prior iterations where pendingEmitText was held back.
376	        size_t const snapLastEmitted = s.lastEmittedTokenCount;
377	        chunk.tokenIds.assign(context.tokenIds[i].begin() + static_cast<std::ptrdiff_t>(snapLastEmitted),
378	            context.tokenIds[i].begin() + static_cast<std::ptrdiff_t>(s.sentTokenCount));
379	        chunk.text = std::move(s.pendingEmitText);
380	        chunk.finished = isFinal;
381	        if (isFinal)
382	        {
383	            chunk.reason = s.terminalReason;
384	        }
385	        if (context.numLogprobs > 0 && static_cast<size_t>(i) < context.stepLogprobs.size())
386	        {
387	            rt::LogprobsSlot const& slot = context.stepLogprobs[i];
388	            int32_t const topK = context.numLogprobs;
389	            size_t const newTokens = s.sentTokenCount - snapLastEmitted;
390	            for (size_t j = 0; j < newTokens; ++j)
391	            {
392	                size_t const stepIdx = s.logprobsEmittedCount + j;
393	                if (stepIdx >= static_cast<size_t>(slot.numSteps))
394	                {
395	                    break;
396	                }
397	                auto const* base = slot.data.data() + static_cast<std::ptrdiff_t>(stepIdx) * topK;
398	                std::vector<LogprobEntry> entries;
399	                entries.reserve(topK);
400	                for (int32_t k = 0; k < topK; ++k)
401	                {
402	                    entries.push_back({base[k].first, base[k].second, tokenizer.idToPiece(base[k].first)});
403	                }
404	                chunk.logprobs.push_back(std::move(entries));
405	            }
406	            s.logprobsEmittedCount += chunk.logprobs.size();
407	        }
408	
409	        s.channel->push(std::move(chunk));
410	        s.lastEmittedTokenCount = s.sentTokenCount;
411	        if (isFinal)
412	        {
413	            s.channel->finish(s.terminalReason);
414	        }
415	    }
416	}
417	
418	//=============================================================================
419	// StreamChannelFinalizer — RAII terminal-chunk guarantee
420	//=============================================================================
421	
422	StreamChannelFinalizer::StreamChannelFinalizer(DecodingInferenceContext& ctx, tokenizer::Tokenizer const& tok) noexcept
423	    : mCtx(ctx)
424	    , mTok(tok)
425	{
426	}
427	
428	StreamChannelFinalizer::~StreamChannelFinalizer() noexcept
429	{
430	    // Destructor runs during unwind on every exit path from handleRequest.
431	    // Allocations in chunk assembly may throw on OOM — swallow them because the
432	    // essential invariant (consumer must unblock) is carried by finish() alone.
433	    for (size_t i = 0; i < mCtx.slotStreams.size(); ++i)
434	    {
435	        auto& s = mCtx.slotStreams[i];
436	        if (!s.channel)
437	        {
438	            continue;
439	        }
440	        if (s.channel->isFinished())
441	        {
442	            continue; // Already terminated via the normal emit path.
443	        }
444	
445	        try
446	        {
447	            StreamChunk chunk;
448	
449	            // Any tokens generated but not yet pushed (held by streamInterval
450	            // or appended just before the aborting exit path).
451	            if (i < mCtx.tokenIds.size() && s.lastEmittedTokenCount < mCtx.tokenIds[i].size())
452	            {
453	                chunk.tokenIds.assign(mCtx.tokenIds[i].begin() + static_cast<std::ptrdiff_t>(s.lastEmittedTokenCount),
454	                    mCtx.tokenIds[i].end());
455	            }
456	            if (mCtx.numLogprobs > 0 && i < mCtx.stepLogprobs.size())
457	            {
458	                rt::LogprobsSlot const& slot = mCtx.stepLogprobs[i];
459	                int32_t const topK = mCtx.numLogprobs;
460	                for (size_t stepIdx = s.logprobsEmittedCount; stepIdx < static_cast<size_t>(slot.numSteps); ++stepIdx)
461	                {
462	                    auto const* base = slot.data.data() + static_cast<std::ptrdiff_t>(stepIdx) * topK;
463	                    std::vector<LogprobEntry> entries;
464	                    entries.reserve(topK);
465	                    for (int32_t k = 0; k < topK; ++k)
466	                    {
467	                        entries.push_back({base[k].first, base[k].second, mTok.idToPiece(base[k].first)});
468	                    }
469	                    chunk.logprobs.push_back(std::move(entries));
470	                }
471	            }
472	
473	            // Decode any un-decoded tokens via idToPiece, then sanitize+flush.
474	            bool const skipSpecial = s.channel->getSkipSpecialTokens();
475	            std::string raw;
476	            if (i < mCtx.tokenIds.size())
477	            {
478	                for (size_t k = s.sentTokenCount; k < mCtx.tokenIds[i].size(); ++k)
479	                {
480	                    raw.append(mTok.idToPiece(mCtx.tokenIds[i][k], skipSpecial));
481	                }
482	            }
483	            chunk.text = utf8::sanitizeUtf8Streaming(raw, s.pendingBytes);
484	            chunk.text.append(utf8::sanitizeUtf8Flush(s.pendingBytes));
485	
486	            chunk.finished = true;
487	            chunk.reason = FinishReason::kError;
488	            s.channel->push(std::move(chunk));
489	        }
490	        catch (...)
491	        {
492	            // Best-effort push; finish() below still unblocks the consumer.
493	        }
494	
495	        s.channel->finish(FinishReason::kError);
496	    }
497	}
498	
499	// Explicit instantiation lives next to the template definition (in
500	// llmRuntimeUtils.cpp). It's forward-declared there with SlotStreamState as
501	// a complete type via this header's include.
502	
503	} // namespace rt
504	} // namespace trt_edgellm
