111	//! Stage 2 of the per-iter pipeline (after updateFinishStates): push chunks
112	//! to channels using the pre-computed `pendingEmitText` and finalized
113	//! `terminalReason`. Non-streaming slots are skipped here — their output is
114	//! assembled at handleRequest finalization. `tokenizer` is used to resolve the
115	//! raw token piece for per-token logprobs (LogprobEntry::piece).
116	void emitChunks(DecodingInferenceContext& context, tokenizer::Tokenizer const& tokenizer);
117	
118	/*! @brief Result of applyStopStringMatch. */
119	struct StopMatchOutcome
120	{
121	    std::string emitted;     //!< Bytes safe to push right now.
122	    bool stopMatched{false}; //!< True iff a stop string was found and triggered truncation.
123	};
124	
125	/*!
126	 * @brief Stop-string match against a per-slot rolling buffer.
127	 *
128	 *  Caller appends new decoded bytes into `buffer` before invoking and passes
129	 *  `maxStopLen = max(stops[*].size())` (cached at request entry; 0 ⇒ no stops
130	 *  or all-empty entries — degenerates to pass-through). On return:
131	 *
132	 *  - Match found (earliest position wins): `emitted` = bytes before the match,
133	 *    `stopMatched = true`, `buffer` cleared.
134	 *  - `isFinal`, no match: full flush — `emitted = buffer`, `buffer` cleared.
135	 *  - Otherwise: emit `buffer` minus its trailing `maxStopLen - 1` bytes; those
136	 *    bytes stay in `buffer` for cross-iteration matching.
137	 *
138	 *  Matching is byte-level; caller must guarantee UTF-8.
139	 */
140	StopMatchOutcome applyStopStringMatch(
141	    std::string& buffer, std::vector<std::string> const& stops, size_t maxStopLen, bool isFinal);
142	
143	/*!
144	 * @brief Per-slot streaming channel.
145	 *
146	 * Encapsulated MPSC pipe between the runtime (producer) and a single consumer.
147	 * State is private; consumer interacts via consume()/waitPop()/tryPop()/cancel().
148	 * Runtime-side operations (push, finish, setOriginalBatchIdx) are accessed via
149	 * friendship so consumers cannot hold the lock or skip chunks.
150	 */
151	class StreamChannel
152	{
153	public:
154	    //! Factory — only way to construct. Enforces shared_ptr ownership.
155	    static std::shared_ptr<StreamChannel> create();
156	
157	    StreamChannel(StreamChannel const&) = delete;
158	    StreamChannel& operator=(StreamChannel const&) = delete;
159	    StreamChannel(StreamChannel&&) = delete;
160	    StreamChannel& operator=(StreamChannel&&) = delete;
161	
162	    ~StreamChannel() noexcept = default;
163	
164	    // ── Consumer API ─────────────────────────────────────────────────────────
165	
166	    /*!
167	     * @brief Block until `finished` or `cancelled`, delivering every chunk.
168	     *
169	     * Exits when `pending` is empty AND either `finished` or `cancelled` is set.
170	     * Lock is held only for pop; `handler` runs with the mutex released.
171	     *
172	     * @tparam Handler Callable with signature `void(StreamChunk&&)`.
173	     * @param handler  Invoked once per chunk delivered.
174	     * @param poll     Max interval between wakeups (defaults to 100ms).
175	     */
176	    template <typename Handler>
177	    void consume(Handler&& handler, std::chrono::milliseconds poll = std::chrono::milliseconds{100});
178	
179	    //! Non-blocking single-chunk pop.
180	    std::optional<StreamChunk> tryPop();
181	
182	    /*!
183	     * @brief Blocking single-chunk pop with timeout.
184	     *
185	     * Returns std::nullopt on timeout, or when woken by finish()/cancel() with
186	     * empty deque. Callers that need the terminal signal should combine
187	     * waitPop() with isFinished()/isCancelled().
188	     */
189	    std::optional<StreamChunk> waitPop(std::chrono::milliseconds timeout);
190	
191	    bool isFinished() const noexcept;
192	    FinishReason getReason() const noexcept;
193	    int32_t getOriginalBatchIdx() const noexcept;
194	    bool isCancelled() const noexcept;
195	
196	    //! Fire-and-forget cancellation. Safe from any thread. Wakes blocked consume/waitPop.
197	    void cancel() noexcept;
198	
199	    //! Per-request emit throttle. Values < 1 are clamped to 1. Default 1.
200	    void setStreamInterval(int32_t n) noexcept;
201	    int32_t getStreamInterval() const noexcept;
202	
203	    //! Filter special tokens (EOS, `<|im_end|>`, `<think>`, vision placeholders,
204	    //! etc.) out of `chunk.text`. Default `true`. `chunk.tokenIds` is unaffected
205	    //! either way. Set before the channel is attached.
206	    void setSkipSpecialTokens(bool skip) noexcept;
207	    bool getSkipSpecialTokens() const noexcept;
208	
209	private:
210	    StreamChannel() = default;
211	    friend class StreamChannelFinalizer;
212	    friend void attachStreamChannel(std::shared_ptr<StreamChannel> const&, int32_t);
213	    friend bool validateStreamingSubmission(LLMGenerationRequest const&);
214	    friend void applyCancellationToFinishStates(DecodingInferenceContext&);
215	    friend void decodePerSlot(DecodingInferenceContext&, tokenizer::Tokenizer const&);
216	    friend void emitChunks(DecodingInferenceContext&, tokenizer::Tokenizer const&);
217	
218	    // ── Producer API (runtime-only) ──────────────────────────────────────────
219	    void push(StreamChunk chunk);
220	    void finish(FinishReason reason); //!< Idempotent: first call wins.
221	    void setOriginalBatchIdx(int32_t idx) noexcept;
222	
223	    mutable std::mutex mMutex;
224	    std::condition_variable mCv;
225	    std::deque<StreamChunk> mPending;
226	
227	    std::atomic<bool> mFinished{false};
228	    std::atomic<FinishReason> mReason{FinishReason::kNotFinished};
229	    std::atomic<bool> mCancelled{false};
230	    std::atomic<int32_t> mOriginalBatchIdx{-1};
231	    std::atomic<int32_t> mStreamInterval{1};
232	    std::atomic<bool> mSkipSpecialTokens{true};
233	
234	    std::atomic<bool> mAttachedToRequest{false};
235	};
236	
237	// Template consume() definition: must be visible in the header.
238	template <typename Handler>
239	void StreamChannel::consume(Handler&& handler, std::chrono::milliseconds poll)
240	{
241	    std::unique_lock<std::mutex> lk(mMutex);
242	    while (true)
243	    {
244	        mCv.wait_for(lk, poll, [&] {
245	            return !mPending.empty() || mFinished.load(std::memory_order_acquire)
246	                || mCancelled.load(std::memory_order_acquire);
247	        });
248	        while (!mPending.empty())
249	        {
250	            StreamChunk chunk = std::move(mPending.front());
251	            mPending.pop_front();
252	            lk.unlock();
253	            std::forward<Handler>(handler)(std::move(chunk));
254	            lk.lock();
255	        }
256	        bool const done = mFinished.load(std::memory_order_acquire) || mCancelled.load(std::memory_order_acquire);
257	        if (done && mPending.empty())
258	        {
259	            break;
260	        }
261	    }
262	}
263	
264	/*!
265	 * @brief Per-slot detokenization and streaming state.
266	 *
267	 * Lives in DecodingInferenceContext, compacted in lockstep with tokenIds.
268	 */
269	struct SlotStreamState
270	{
271	    //! Channel (null ⇒ streaming disabled for this slot).
272	    std::shared_ptr<StreamChannel> channel;
273	
274	    //! Count of tokens whose piece bytes have been fed through emitDelta.
275	    size_t sentTokenCount{0};
276	
277	    //! sentTokenCount at last push (for streamInterval gating).
278	    size_t lastEmittedTokenCount{0};
279	
280	    //! Number of logprob steps already pushed (0-based, independent of prompt length).
281	    size_t logprobsEmittedCount{0};
282	
283	    //! Trailing incomplete UTF-8 bytes carried across iterations.
284	    std::string pendingBytes;
285	
286	    //! Terminal reason latched at the moment finishedStates[i] flips to 1.
287	    //! One writer (the code that flips the state), one reader (the emit hook).
288	    FinishReason terminalReason{FinishReason::kNotFinished};
289	
290	    //! Hold-back buffer for cross-iteration stop-string matching; bounded by maxStopLen - 1 bytes.
291	    std::string stopMatchBuffer;
292	
293	    //! Cached max(stopStrings[*].size()) for this slot; 0 if no stops. Pre-computed
294	    //! once at handleRequest entry so applyStopStringMatch can skip the per-call scan.
295	    size_t maxStopLen{0};
296	
297	    //! Per-iteration emit text; populated by decodePerSlot, consumed (moved out) by emitChunks.
298	    //! Empty between iterations.
299	    std::string pendingEmitText;
300	
301	    //! True iff stop-string match fired in decodePerSlot this iteration. Read by
302	    //! updateFinishStates to apply the kStopWords override; reset at top of each
303	    //! decodePerSlot pass.
304	    bool stopMatchedThisIter{false};
305	};
306	
307	/*!
308	 * @brief RAII guard that guarantees every attached StreamChannel terminates.
309	 *
310	 * On destruction, for every slot whose channel has not yet been finalized the
311	 * guard:
312	 *   1. Tries to build a terminal chunk containing any un-emitted tokens + text
313	 *      (sanitized + flushed to U+FFFD) with reason=kError and push()es it.
314	 *   2. Calls finish(kError) — idempotent, no-throw — to guarantee the consumer
315	 *      unblocks even if (1) failed under OOM.
316	 */
317	class StreamChannelFinalizer
318	{
319	public:
320	    StreamChannelFinalizer(DecodingInferenceContext& ctx, tokenizer::Tokenizer const& tok) noexcept;
321	    ~StreamChannelFinalizer() noexcept;
322	
323	    StreamChannelFinalizer(StreamChannelFinalizer const&) = delete;
324	    StreamChannelFinalizer& operator=(StreamChannelFinalizer const&) = delete;
325	    StreamChannelFinalizer(StreamChannelFinalizer&&) = delete;
326	    StreamChannelFinalizer& operator=(StreamChannelFinalizer&&) = delete;
327	
328	private:
329	    DecodingInferenceContext& mCtx;
330	    tokenizer::Tokenizer const& mTok;
331	};
